from pathlib import Path
import sys

ROOT = Path.cwd()
PAGE = ROOT / "app/(portal)/ranking/page.tsx"
SIDEBAR = ROOT / "components/portal/portal-sidebar.tsx"

def fail(message):
    print(f"\nERROR: {message}")
    sys.exit(1)

def main():
    if not SIDEBAR.exists():
        fail(
            "Run this from the sepulchria-portal repository root. "
            f"Missing: {SIDEBAR.relative_to(ROOT)}"
        )

    print("Building The Hall of Renown...")
    print("Built against commit 6a1ec8c.")
    print("No GitHub or Vercel operations are performed.\n")

    PAGE.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    PAGE.write_text(
        'import Link from "next/link";\n\nimport {\n  createAdminClient,\n} from "@/lib/supabase/admin";\n\ntype Props = {\n  searchParams?: Promise<{\n    board?: string;\n  }>;\n};\n\ntype CharacterRow = {\n  id: string;\n  user_id: string | null;\n  display_name: string | null;\n  portrait_url: string | null;\n  public_slug: string;\n};\n\ntype MetricRow = {\n  metric_key: string;\n  metric_value:\n    | number\n    | string\n    | null;\n};\n\ntype RankingCharacter =\n  CharacterRow & {\n    metrics: Map<string, number>;\n    accountCreatedAt: string | null;\n  };\n\ntype BoardDefinition = {\n  key: string;\n  label: string;\n  eyebrow: string;\n  description: string;\n  metricKeys?: string[];\n  hiddenValue?: boolean;\n  valueLabel?: string;\n  valueSuffix?: string;\n  veteran?: boolean;\n};\n\nconst boards: BoardDefinition[] = [\n  {\n    key: "expertise",\n    label: "Most Experienced",\n    eyebrow: "Expertise",\n    description:\n      "Those who have accumulated the greatest total Expertise.",\n    metricKeys: ["expertise_total"],\n    valueLabel: "Expertise",\n  },\n  {\n    key: "veterans",\n    label: "Veterans",\n    eyebrow: "Standing",\n    description:\n      "The longest-standing players of Sepulchria, ordered by account registration.",\n    veteran: true,\n  },\n  {\n    key: "earners",\n    label: "Top Earners",\n    eyebrow: "Economy",\n    description:\n      "Those who have earned the most Remnants over their lifetime. Exact amounts remain private.",\n    metricKeys: [\n      "remnants_lifetime_earned",\n    ],\n    hiddenValue: true,\n  },\n  {\n    key: "spenders",\n    label: "Biggest Spenders",\n    eyebrow: "Economy",\n    description:\n      "Those who have spent the most Remnants over their lifetime. Exact amounts remain private.",\n    metricKeys: [\n      "remnants_lifetime_spent",\n    ],\n    hiddenValue: true,\n  },\n  {\n    key: "collectors",\n    label: "Collectors",\n    eyebrow: "Inventory",\n    description:\n      "Those who have owned the widest variety of Item types over their lifetime.",\n    metricKeys: [\n      "inventory_item_types_ever_owned",\n      "item_types_ever_owned",\n      "inventory_types_ever_owned",\n      "distinct_items_ever_owned",\n    ],\n    valueLabel: "Item types",\n  },\n  {\n    key: "shapes",\n    label: "Shape Masters",\n    eyebrow: "Warping",\n    description:\n      "Those who have accumulated the greatest number of Shapes.",\n    metricKeys: [\n      "shapes_owned",\n      "shapes_known",\n      "shape_count",\n    ],\n    valueLabel: "Shapes",\n  },\n  {\n    key: "feats",\n    label: "Feat Masters",\n    eyebrow: "Feats",\n    description:\n      "Those who have acquired the greatest number of Feats.",\n    metricKeys: [\n      "feats_owned",\n      "feats_known",\n      "feat_count",\n    ],\n    valueLabel: "Feats",\n  },\n  {\n    key: "recipes",\n    label: "Recipe Masters",\n    eyebrow: "Crafting",\n    description:\n      "Those who know the greatest number of crafting Recipes.",\n    metricKeys: [\n      "recipes_known",\n      "recipe_count",\n      "known_recipes",\n    ],\n    valueLabel: "Recipes",\n  },\n  {\n    key: "market",\n    label: "Market Regulars",\n    eyebrow: "Market",\n    description:\n      "Those with the greatest lifetime Market activity.",\n    metricKeys: [\n      "market_transactions",\n      "market_transactions_total",\n      "market_activity_total",\n      "market_actions_total",\n    ],\n    valueLabel: "Transactions",\n  },\n  {\n    key: "odd-jobs",\n    label: "Odd Job Workers",\n    eyebrow: "Work",\n    description:\n      "Those who have completed the greatest number of Odd Jobs.",\n    metricKeys: [\n      "odd_jobs_completed",\n      "jobs_completed",\n      "odd_job_completions",\n    ],\n    valueLabel: "Completed",\n  },\n  {\n    key: "gamblers",\n    label: "Gamblers",\n    eyebrow: "House of Chances",\n    description:\n      "Those who have played at the House of Chances most often.",\n    metricKeys: [\n      "chances_plays",\n      "house_of_chances_plays",\n      "chance_plays",\n    ],\n    valueLabel: "Plays",\n  },\n  {\n    key: "luckiest",\n    label: "Luckiest",\n    eyebrow: "House of Chances",\n    description:\n      "Those with the greatest number of House of Chances wins.",\n    metricKeys: [\n      "chances_wins",\n      "house_of_chances_wins",\n      "chance_wins",\n    ],\n    valueLabel: "Wins",\n  },\n  {\n    key: "breeze",\n    label: "Breeze Residents",\n    eyebrow: "The Breeze",\n    description:\n      "Those who have rented rooms at The Breeze for the greatest total number of days.",\n    metricKeys: [\n      "breeze_days_rented",\n      "breeze_rental_days",\n      "lodging_days_rented",\n    ],\n    valueLabel: "Days",\n  },\n  {\n    key: "forum",\n    label: "Forum Contributors",\n    eyebrow: "Forum",\n    description:\n      "Those who have contributed the greatest number of Forum posts.",\n    metricKeys: [\n      "forum_posts",\n      "forum_posts_total",\n      "forum_messages_sent",\n    ],\n    valueLabel: "Posts",\n  },\n  {\n    key: "correspondents",\n    label: "Correspondents",\n    eyebrow: "Messages",\n    description:\n      "Those who have sent the greatest number of private messages.",\n    metricKeys: [\n      "private_messages_sent",\n      "direct_messages_sent",\n      "messages_sent",\n    ],\n    valueLabel: "Messages",\n  },\n  {\n    key: "chatters",\n    label: "Instant Chatters",\n    eyebrow: "Conversation",\n    description:\n      "Those with the greatest lifetime instant-chat activity.",\n    metricKeys: [\n      "instant_chat_messages",\n      "instant_chat_messages_sent",\n      "chat_messages_sent",\n      "room_messages_sent",\n    ],\n    valueLabel: "Messages",\n  },\n  {\n    key: "premium",\n    label: "Premium Collectors",\n    eyebrow: "Premium",\n    description:\n      "Those who have acquired the greatest number of Premium features and entitlements.",\n    metricKeys: [\n      "premium_features_ever_owned",\n      "premium_acquisitions",\n      "premium_features_owned",\n      "premium_entitlements_ever",\n    ],\n    valueLabel: "Acquisitions",\n  },\n];\n\nfunction asNumber(\n  value:\n    | number\n    | string\n    | null\n    | undefined,\n) {\n  const parsed =\n    Number(value ?? 0);\n\n  return Number.isFinite(parsed)\n    ? parsed\n    : 0;\n}\n\nfunction findMetric(\n  character: RankingCharacter,\n  keys: string[] = [],\n) {\n  for (const key of keys) {\n    if (\n      character.metrics.has(key)\n    ) {\n      return (\n        character.metrics.get(key) ??\n        0\n      );\n    }\n  }\n\n  return 0;\n}\n\nfunction formatNumber(\n  value: number,\n) {\n  return new Intl.NumberFormat(\n    "en-GB",\n    {\n      maximumFractionDigits: 2,\n    },\n  ).format(value);\n}\n\nfunction formatDate(\n  value: string | null,\n) {\n  if (!value) {\n    return "Unknown";\n  }\n\n  const date = new Date(value);\n\n  if (\n    Number.isNaN(\n      date.getTime(),\n    )\n  ) {\n    return "Unknown";\n  }\n\n  return new Intl.DateTimeFormat(\n    "en-GB",\n    {\n      day: "2-digit",\n      month: "short",\n      year: "numeric",\n    },\n  ).format(date);\n}\n\nfunction rankingValue(\n  character: RankingCharacter,\n  board: BoardDefinition,\n) {\n  if (board.veteran) {\n    if (\n      !character.accountCreatedAt\n    ) {\n      return Number.POSITIVE_INFINITY;\n    }\n\n    return new Date(\n      character.accountCreatedAt,\n    ).getTime();\n  }\n\n  return findMetric(\n    character,\n    board.metricKeys,\n  );\n}\n\nfunction sortForBoard(\n  characters: RankingCharacter[],\n  board: BoardDefinition,\n) {\n  return [...characters]\n    .filter((character) => {\n      if (board.veteran) {\n        return Boolean(\n          character.accountCreatedAt,\n        );\n      }\n\n      return (\n        rankingValue(\n          character,\n          board,\n        ) > 0\n      );\n    })\n    .sort((a, b) => {\n      const aValue =\n        rankingValue(a, board);\n      const bValue =\n        rankingValue(b, board);\n\n      if (board.veteran) {\n        return aValue - bValue;\n      }\n\n      if (bValue !== aValue) {\n        return bValue - aValue;\n      }\n\n      return (\n        (\n          a.display_name ??\n          ""\n        ).localeCompare(\n          b.display_name ?? "",\n        )\n      );\n    })\n    .slice(0, 10);\n}\n\nfunction rankLabel(index: number) {\n  if (index === 0) {\n    return "I";\n  }\n\n  if (index === 1) {\n    return "II";\n  }\n\n  if (index === 2) {\n    return "III";\n  }\n\n  return String(index + 1);\n}\n\nexport const dynamic =\n  "force-dynamic";\n\nexport default async function RankingPage({\n  searchParams,\n}: Props) {\n  const params =\n    (await searchParams) ?? {};\n\n  const board =\n    boards.find(\n      (entry) =>\n        entry.key ===\n        params.board,\n    ) ??\n    boards[0];\n\n  const admin =\n    createAdminClient();\n\n  const {\n    data: characterData,\n    error: characterError,\n  } = await admin\n    .from("characters")\n    .select(\n      "id, user_id, display_name, portrait_url, public_slug",\n    )\n    .eq("status", "approved")\n    .eq("is_system", false)\n    .order("display_name", {\n      ascending: true,\n    });\n\n  if (characterError) {\n    throw new Error(\n      `Unable to load Hall of Renown characters: ${characterError.message}`,\n    );\n  }\n\n  const characters =\n    (characterData ??\n      []) as CharacterRow[];\n\n  const metricResults =\n    await Promise.all(\n      characters.map(\n        async (character) => {\n          const result =\n            await admin.rpc(\n              "get_character_trophy_metrics",\n              {\n                p_character_id:\n                  character.id,\n              },\n            );\n\n          if (result.error) {\n            console.error(\n              `Unable to load ranking metrics for ${character.id}:`,\n              result.error.message,\n            );\n\n            return {\n              characterId:\n                character.id,\n              metrics:\n                new Map<\n                  string,\n                  number\n                >(),\n            };\n          }\n\n          const map =\n            new Map<\n              string,\n              number\n            >();\n\n          for (\n            const row of\n            (result.data ??\n              []) as MetricRow[]\n          ) {\n            map.set(\n              row.metric_key,\n              asNumber(\n                row.metric_value,\n              ),\n            );\n          }\n\n          return {\n            characterId:\n              character.id,\n            metrics: map,\n          };\n        },\n      ),\n    );\n\n  const metricsByCharacter =\n    new Map(\n      metricResults.map(\n        (entry) => [\n          entry.characterId,\n          entry.metrics,\n        ],\n      ),\n    );\n\n  const createdAtByUser =\n    new Map<\n      string,\n      string\n    >();\n\n  try {\n    const {\n      data: authUsers,\n      error: authUsersError,\n    } =\n      await admin.auth.admin\n        .listUsers({\n          page: 1,\n          perPage: 1000,\n        });\n\n    if (authUsersError) {\n      console.error(\n        "Unable to load account registration dates:",\n        authUsersError.message,\n      );\n    } else {\n      for (\n        const user of\n        authUsers.users\n      ) {\n        createdAtByUser.set(\n          user.id,\n          user.created_at,\n        );\n      }\n    }\n  } catch (error) {\n    console.error(\n      "Unable to load account registration dates:",\n      error,\n    );\n  }\n\n  const rankingCharacters:\n    RankingCharacter[] =\n    characters.map(\n      (character) => ({\n        ...character,\n        metrics:\n          metricsByCharacter.get(\n            character.id,\n          ) ??\n          new Map(),\n        accountCreatedAt:\n          character.user_id\n            ? createdAtByUser.get(\n                character.user_id,\n              ) ?? null\n            : null,\n      }),\n    );\n\n  const ranked =\n    sortForBoard(\n      rankingCharacters,\n      board,\n    );\n\n  return (\n    <main\n      data-sep-interaction-ignore="true"\n      className="mx-auto w-full max-w-7xl p-3 sm:p-4 lg:p-5"\n    >\n      <header className="bg-[rgb(var(--sep-colour-17110d))] px-5 py-5 sm:px-6">\n        <p className="text-[8px] uppercase tracking-[0.3em] text-[rgb(var(--sep-colour-8c704b))]">\n          Sepulchria remembers\n        </p>\n\n        <div className="mt-1 flex flex-wrap items-end justify-between gap-4">\n          <div>\n            <h1 className="font-serif text-3xl text-[rgb(var(--sep-colour-ead5ac))] sm:text-4xl">\n              The Hall of Renown\n            </h1>\n\n            <p className="mt-2 max-w-3xl text-[11px] leading-5 text-[rgb(var(--sep-colour-928674))]">\n              The deeds, achievements\n              and standing of those\n              whose lives leave their\n              mark upon Sepulchria.\n            </p>\n          </div>\n\n          <div className="bg-[rgb(var(--sep-colour-100c09))] px-4 py-2 text-right">\n            <p className="text-[7px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-756249))]">\n              Records\n            </p>\n\n            <p className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-d0b27e))]">\n              {boards.length}\n            </p>\n          </div>\n        </div>\n      </header>\n\n      <div className="mt-4 grid gap-4 xl:grid-cols-[270px_minmax(0,1fr)]">\n        <aside className="bg-[rgb(var(--sep-colour-120d0a))] p-2">\n          <p className="px-3 py-2 text-[8px] uppercase tracking-[0.22em] text-[rgb(var(--sep-colour-806b4f))]">\n            Records of Renown\n          </p>\n\n          <nav className="space-y-1">\n            {boards.map(\n              (entry) => {\n                const active =\n                  entry.key ===\n                  board.key;\n\n                return (\n                  <Link\n                    key={entry.key}\n                    href={`/ranking?board=${entry.key}`}\n                    scroll={false}\n                    className={`block px-3 py-2.5 transition ${\n                      active\n                        ? "bg-[rgb(var(--sep-colour-302116))] text-[rgb(var(--sep-colour-efd7a7))]"\n                        : "text-[rgb(var(--sep-colour-a7977f))] hover:bg-[rgb(var(--sep-colour-1d1611))] hover:text-[rgb(var(--sep-colour-d8c19a))]"\n                    }`}\n                  >\n                    <span className="block text-[7px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-735f45))]">\n                      {\n                        entry.eyebrow\n                      }\n                    </span>\n\n                    <span className="mt-0.5 block font-serif text-[15px]">\n                      {entry.label}\n                    </span>\n                  </Link>\n                );\n              },\n            )}\n          </nav>\n        </aside>\n\n        <section className="min-w-0 bg-[rgb(var(--sep-colour-120d0a))]">\n          <header className="bg-[rgb(var(--sep-colour-17110d))] px-5 py-4">\n            <p className="text-[8px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-836b4a))]">\n              {board.eyebrow}\n            </p>\n\n            <h2 className="mt-1 font-serif text-2xl text-[rgb(var(--sep-colour-e1c99c))]">\n              {board.label}\n            </h2>\n\n            <p className="mt-2 max-w-3xl text-[11px] leading-5 text-[rgb(var(--sep-colour-8f816e))]">\n              {board.description}\n            </p>\n          </header>\n\n          {ranked.length ? (\n            <div className="space-y-2 p-3 sm:p-4">\n              {ranked.map(\n                (\n                  character,\n                  index,\n                ) => {\n                  const value =\n                    rankingValue(\n                      character,\n                      board,\n                    );\n\n                  const podium =\n                    index < 3;\n\n                  return (\n                    <Link\n                      key={\n                        character.id\n                      }\n                      href={`/characters/${character.public_slug}`}\n                      data-sep-interactive-surface="row"\n                      className={`grid min-h-[72px] grid-cols-[48px_52px_minmax(0,1fr)_auto] items-center gap-3 px-3 py-2.5 transition ${\n                        podium\n                          ? "bg-[rgb(var(--sep-colour-24190f))]"\n                          : "bg-[rgb(var(--sep-colour-15100d))]"\n                      }`}\n                    >\n                      <div\n                        className={`flex h-10 w-10 items-center justify-center font-serif ${\n                          podium\n                            ? "text-xl text-[rgb(var(--sep-colour-e4c47f))]"\n                            : "text-base text-[rgb(var(--sep-colour-82725f))]"\n                        }`}\n                      >\n                        {rankLabel(\n                          index,\n                        )}\n                      </div>\n\n                      <div className="h-12 w-12 overflow-hidden bg-[rgb(var(--sep-colour-0c0907))]">\n                        {character.portrait_url ? (\n                          // eslint-disable-next-line @next/next/no-img-element\n                          <img\n                            src={\n                              character.portrait_url\n                            }\n                            alt=""\n                            className="h-full w-full object-cover"\n                          />\n                        ) : (\n                          <div className="flex h-full w-full items-center justify-center font-serif text-xl text-[rgb(var(--sep-colour-655848))]">\n                            ?\n                          </div>\n                        )}\n                      </div>\n\n                      <div className="min-w-0">\n                        <p\n                          className={`truncate font-serif ${\n                            podium\n                              ? "text-lg text-[rgb(var(--sep-colour-e5ce9f))]"\n                              : "text-base text-[rgb(var(--sep-colour-cbb58f))]"\n                          }`}\n                        >\n                          {character.display_name ??\n                            "Unnamed character"}\n                        </p>\n\n                        <p className="mt-0.5 text-[7px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-695d4e))]">\n                          {index === 0\n                            ? "First in the record"\n                            : `Rank ${index + 1}`}\n                        </p>\n                      </div>\n\n                      <div className="min-w-[100px] text-right">\n                        {board.hiddenValue ? (\n                          <>\n                            <p className="text-[7px] uppercase tracking-[0.17em] text-[rgb(var(--sep-colour-6f604d))]">\n                              Standing\n                            </p>\n\n                            <p className="mt-1 font-serif text-base text-[rgb(var(--sep-colour-bda375))]">\n                              Recorded\n                            </p>\n                          </>\n                        ) : board.veteran ? (\n                          <>\n                            <p className="text-[7px] uppercase tracking-[0.17em] text-[rgb(var(--sep-colour-6f604d))]">\n                              Joined\n                            </p>\n\n                            <p className="mt-1 text-[10px] text-[rgb(var(--sep-colour-bda375))]">\n                              {formatDate(\n                                character.accountCreatedAt,\n                              )}\n                            </p>\n                          </>\n                        ) : (\n                          <>\n                            <p className="text-[7px] uppercase tracking-[0.17em] text-[rgb(var(--sep-colour-6f604d))]">\n                              {board.valueLabel ??\n                                "Total"}\n                            </p>\n\n                            <p className="mt-1 font-serif text-lg text-[rgb(var(--sep-colour-d0b27e))]">\n                              {formatNumber(\n                                value,\n                              )}\n                              {board.valueSuffix ??\n                                ""}\n                            </p>\n                          </>\n                        )}\n                      </div>\n                    </Link>\n                  );\n                },\n              )}\n            </div>\n          ) : (\n            <div className="px-5 py-14 text-center">\n              <p className="font-serif text-xl text-[rgb(var(--sep-colour-a98e68))]">\n                No names have yet been\n                entered into this record.\n              </p>\n\n              <p className="mt-2 text-[10px] text-[rgb(var(--sep-colour-706554))]">\n                The Hall will update as\n                characters leave their\n                mark upon Sepulchria.\n              </p>\n            </div>\n          )}\n        </section>\n      </div>\n\n      <p className="mt-4 text-center text-[8px] leading-4 text-[rgb(var(--sep-colour-62594e))]">\n        Current Remnant balances are\n        never displayed in the Hall of\n        Renown. Lifetime economy records\n        reveal standing only where\n        amounts are private.\n      </p>\n    </main>\n  );\n}\n',
        encoding="utf-8",
    )

    print(
        "CREATED: app\\(portal)\\ranking\\page.tsx"
    )

    text = SIDEBAR.read_text(
        encoding="utf-8",
    )

    old = """const rankingItem: NavigationItem = {
  label: "Ranking",
  title:
    "View Sepulchria character rankings and lifetime achievements.",
  icon: "/icons/characters.png",
  href: "/ranking",
  activePaths: ["/ranking"],
};"""

    new = """const rankingItem: NavigationItem = {
  label: "Hall of Renown",
  title:
    "Enter the Hall of Renown and view Sepulchria's records of standing and achievement.",
  icon: "/icons/characters.png",
  href: "/ranking",
  activePaths: ["/ranking"],
};"""

    if old in text:
        text = text.replace(
            old,
            new,
            1,
        )
    elif 'label: "Hall of Renown"' not in text:
        fail(
            "Could not find the Ranking sidebar item."
        )

    SIDEBAR.write_text(
        text,
        encoding="utf-8",
    )

    print(
        "UPDATED: components\\portal\\portal-sidebar.tsx"
    )

    print("\nSUCCESS.")
    print("\nThe Hall includes:")
    print("  - Most Experienced")
    print("  - Veterans")
    print("  - Top Earners")
    print("  - Biggest Spenders")
    print("  - Collectors")
    print("  - Shape Masters")
    print("  - Feat Masters")
    print("  - Recipe Masters")
    print("  - Market Regulars")
    print("  - Odd Job Workers")
    print("  - Gamblers")
    print("  - Luckiest")
    print("  - Breeze Residents")
    print("  - Forum Contributors")
    print("  - Correspondents")
    print("  - Instant Chatters")
    print("  - Premium Collectors")
    print("\nNow run:")
    print("  npm run build")

if __name__ == "__main__":
    main()
